create or alter function [dbo].[GetCombinedPermissionsForUserByAssetTypeLegacy] 
(
	@object varchar(50),
	@objectId int,
	@userId int
)
returns int
as
begin
	declare @id int,
			@combinedPermissionMask int = 0;
	select	@id = ID from dbo.AssetType where Object = @object and ObjectID = @objectId;
	select	@combinedPermissionMask = dbo.GetCombinedPermissionsForUserByAssetTypeId(@id, @userId);
	return	@combinedPermissionMask;
end
